data = read('/input/data')
nodes = data['nodes']
start = data['start']
dist = {}
for node in nodes:
    dist = putmap(dist, node, -1)
dist = putmap(dist, start, 0)
remaining = nodes
for step in range(len(nodes)):
    changed = False
    for edge in data['edges']:
        u = edge['u']
        v = edge['v']
        weight = edge['weight']
        du = get(dist, u, -1)
        dv = get(dist, v, -1)
        if du != -1:
            candidate = du + weight
            if dv == -1 or candidate < dv:
                dist = putmap(dist, v, candidate)
                changed = True
    if not changed:
        break
ordered = sorted(nodes)
main = [{'id': node, 'distance': get(dist, node, -1)} for node in ordered]
result = {'main': main}
